import{a as e,i as t,r as n,t as r}from"./app-Dkwa1Gla.js";var i=JSON.parse(`{"path":"/%E7%AC%AC01%E7%AB%A0%20%E4%BF%A1%E6%81%AF%E5%8C%96%E5%8F%91%E5%B1%95/1.2%20%E7%8E%B0%E4%BB%A3%E5%8C%96%E5%9F%BA%E7%A1%80%E8%AE%BE%E6%96%BD.html","title":"1.2 现代化基础设施","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第01章 信息化发展/1.2 现代化基础设施.md"}`),a={name:`1.2 现代化基础设施.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="_1-2-现代化基础设施" tabindex="-1"><a class="header-anchor" href="#_1-2-现代化基础设施"><span>1.2 现代化基础设施</span></a></h1><h2 id="_1-2-1-新型基础设施建设" tabindex="-1"><a class="header-anchor" href="#_1-2-1-新型基础设施建设"><span>1.2.1 新型基础设施建设</span></a></h2><h3 id="新基建领域" tabindex="-1"><a class="header-anchor" href="#新基建领域"><span>新基建领域</span></a></h3><p>5G、人工智能、大数据中心、工业互联网、特高压、城际高速铁路和轨道交通、新能源充电桩</p><h3 id="发展理念" tabindex="-1"><a class="header-anchor" href="#发展理念"><span>发展理念</span></a></h3><p>新发展理念为引领(理念引领)，以技术创新为驱动(创新驱动)，信息网络为基础(网络基础)</p><h3 id="内容" tabindex="-1"><a class="header-anchor" href="#内容"><span>内容</span></a></h3><ol><li><strong>信息基础设施（技术新）</strong><ol><li>以5G、物联网、工业互联网、卫星互联网为代表的<strong>通信网络基础设施</strong></li><li>以人工智能、云计算、区块链等为代表的<strong>新技术基础设施</strong></li><li>以数据中心、智能计算中心为代表的<strong>算力基础设施</strong></li></ol></li><li><strong>融合基础设施（应用新）</strong></li></ol><p>深度应用互联网、大数据、人工智能等技术，支撑传统基础设施转型升级</p><p>智能交通基础设施、智慧能源基础设施</p><ol start="3"><li><strong>创新基础设施（平台新）</strong></li></ol><p>支撑科学研究、技术开发、产品研制的具有公益属性的基础设施</p><p>重大科技基础设施、科教基础设施、产业技术创新基础设施</p><h3 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h3><p>是新一代信息通信技术与工业经济深度融合的新型基础设施、应用模式和工业生态，通过对人、机、物、系统等的全面连接，构建起覆盖全产业链、全价值链的全新制造和服务体系，为工业乃至产业数字化、网络化、智能化发展提供了实现途径</p><h2 id="_1-2-2-工业互联网" tabindex="-1"><a class="header-anchor" href="#_1-2-2-工业互联网"><span>1.2.2 工业互联网</span></a></h2><h3 id="内涵外延" tabindex="-1"><a class="header-anchor" href="#内涵外延"><span>内涵外延</span></a></h3><p>工业互联网不是互联网在工业的简单应用，是具有更为丰富的内涵和外延，它既是工业数字化、网络化、智能化转型的基础设施，也是互联网、大数据、人工智能与实体经济深度融合的应用模式，同时也是一种新业态、新产业，将重塑企业形态、供应链和产业链</p><p>【以网络为基础，平台为中枢，数据为要素，安全为保障】——记忆：保安/纪要/忘/台中</p><h3 id="平台体系" tabindex="-1"><a class="header-anchor" href="#平台体系"><span>平台体系</span></a></h3><h4 id="_1-网络是基础" tabindex="-1"><a class="header-anchor" href="#_1-网络是基础"><span>1. 网络是基础</span></a></h4><p>【工业互联网网络体系包括网络互联、数据互通和标识解析】——联通标</p><ol><li><strong>网络互联</strong></li></ol><p>实现要素之间的数据传输，包括企业外网和企业内网</p><p>典型技术包括传统的工业总线、工业以太网以及创新的时间敏感网络(TSN)、确定性网络、5G等技术</p><ol start="2"><li><strong>数据互通</strong></li></ol><p>通过对数据进行标准化描述和统一建模，实现要素之间传输信息的相互理解，数据互通涉及数据传输、数据语义语法等不同层面</p><ol start="3"><li><strong>标识解析</strong></li></ol><p>实现要素的标记、管理和定位，由标识编码、标识解析系统和标识数据服务组成，通过为物料、机器、产品等物理资源和工序、软件、模型、数据等虚拟资源分配标识编码，实现物理实体和虚拟对象的逻辑定位和信息查询，支撑跨企业、跨地区、跨行业的数据共享共用</p><h4 id="_2-平台为中枢" tabindex="-1"><a class="header-anchor" href="#_2-平台为中枢"><span>2. 平台为中枢</span></a></h4><p>平台体系包括边缘层、IaaS、PaaS和SaaS四个层级，相当于工业互联网的操作系统</p><p>四个主要作用：</p><ol><li><strong>数据汇聚</strong></li></ol><p>网络层面采集的多源、异构、海量数据，传输至工业互联网平台，为深度分析和应用提供基础</p><ol start="2"><li><strong>建模分析</strong></li></ol><p>提供大数据、人工智能分析的算法模型和物理、化学等各类仿真工具，结合数字孪生、工业智能等技术，对海量数据挖掘分析，实现数据驱动的科学决策和智能应用</p><ol start="3"><li><strong>知识复用</strong></li></ol><p>将工业经验知识转化为平台上的模型库、知识库，并通过工业微服务组件方式，方便二次开发和重复调用，加速共性能力沉淀和普及</p><ol start="4"><li><strong>应用创新</strong></li></ol><p>面向研发设计、设备管理、企业运营、资源调度等场景，提供各类工业App、云化软件，帮助企业提质增效</p><h4 id="_3-数据为要素" tabindex="-1"><a class="header-anchor" href="#_3-数据为要素"><span>3. 数据为要素</span></a></h4><p>有三个特性：①重要性；②专业性；③复杂性 ——重复业</p><h4 id="_4-安全为保障" tabindex="-1"><a class="header-anchor" href="#_4-安全为保障"><span>4. 安全为保障</span></a></h4><p>三大特点：①涉及范围广；②造成影响大；③企业防护基础弱 ——广大弱</p><h3 id="工业互联网融合应用" tabindex="-1"><a class="header-anchor" href="#工业互联网融合应用"><span>工业互联网融合应用</span></a></h3><ol><li><strong>平台化设计</strong>：把所有设计资源放在一个平台上，多人协作、快速迭代</li><li><strong>智能化制造</strong>：机器自动生产，AI替代人工，提高效率减少错误</li><li><strong>网络化协同</strong>：供应链上下游企业数据共享，协同工作，就像拼乐高</li><li><strong>个性化定制</strong>：根据你的需求量身定做，批量生产但每个都不同</li><li><strong>服务化延伸</strong>：不只卖产品，还提供全套服务，从&quot;卖东西&quot;到&quot;卖解决方案&quot;</li><li><strong>数字化管理</strong>：用数据驱动决策，所有环节数字化，实时监控优化</li></ol><h2 id="_1-2-3-车联网" tabindex="-1"><a class="header-anchor" href="#_1-2-3-车联网"><span>1.2.3 车联网</span></a></h2><h3 id="定义-1" tabindex="-1"><a class="header-anchor" href="#定义-1"><span>定义</span></a></h3><p>新一代网络通信技术与汽车、电子、道路交通运输等领域深度融合的新兴产业形态</p><h3 id="体系框架" tabindex="-1"><a class="header-anchor" href="#体系框架"><span>体系框架</span></a></h3><ol><li><strong>端系统</strong></li></ol><p>是汽车的智能传感器负责采集与获取车辆的智能信息，感知行车状态与环境；是具有车内通信、车间通信、车网通信的泛在通信终端；同时还是让汽车具备IOV寻址和网络可信标识等能力的设备</p><ol start="2"><li><strong>管系统</strong></li></ol><p>解决车与车、车与路、车与网、车与人等的互联互通，实现车辆自组网及多种异构网络之间的通信与漫游，在功能和性能上保障实时性、可服务性与网络泛在性，同时它是公网与专网的统一体</p><ol start="3"><li><strong>云系统</strong></li></ol><p>是一个云架构的车辆运行信息平台，它的生态包含了ITS、物流、客货运、危特车辆、汽修汽配、汽车租赁、企事业车辆管理、汽车制造商、4S店、车管、保险、紧急救援、移动互联网等，是多源海量信息的汇聚，因此需要虚拟化、安全认证、实时交互海量存储等云计算功能，其应用系统也是围绕车辆的数据汇聚、计算、调度、监控、管理与应用的复合体系</p><h3 id="链接方式" tabindex="-1"><a class="header-anchor" href="#链接方式"><span>链接方式</span></a></h3><ol><li><strong>车与云平台</strong></li></ol><p>车辆通过卫星无线通信或移动蜂窝等无线通信技术实现与车联网服务平台的信息传输，接收平台下达的控制指令，实时共享车辆数据</p><ol start="2"><li><strong>车与车</strong></li></ol><p>车辆与车辆之间实现信息交流与信息共享，包括车辆位置、行驶速度等车辆状态信息，可用于判断道路车流状况</p><ol start="3"><li><strong>车与路</strong></li></ol><p>借助地面道路固定通信设施实现车辆与道路间的信息交流，用于监测道路路面状况，引导车辆选择最佳行驶路径</p><ol start="4"><li><strong>车与人</strong></li></ol><p>用户可以通过Wi-Fi、蓝牙、蜂窝等无线通信手段与车辆进行信息沟通，使用户能通过对应的移动终端设备监测并控制车辆</p><ol start="5"><li><strong>车内设备</strong></li></ol><p>车辆内部各设备间的信息数据传输，用于对设备状态的实时检测与运行控制，建立数字化的车内控制系统</p>`,67)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};